from pathlib import Path
def change(p,a,b):
 f=Path(p);s=f.read_text(encoding='utf-8-sig')
 if a not in s: raise RuntimeError('Pattern not found: '+p+' '+a[:70])
 f.write_text(s.replace(a,b),encoding='utf-8')
